/* CYCLOPS professional courses: narrated slide presentations with the code requirements inspectors use on the job
   (calibration blocks, reference levels, IQI, density, dwell times, test pressures, test loads, acceptance criteria).
   Each value carries its source and a status badge:
     checked = cross-checked against public secondary sources (not the paid code text);
     verify  = from training knowledge, the code text could not be consulted.
   Codes are copyrighted and revised: these are short working summaries, and the edition in force, the contract, the
   approved procedure and the qualified Level 3 / inspector always decide. Training content, not a qualification.
   window.CYPRO = { open(course) } */
(function () {
  'use strict';
  const L = (en, fr) => (typeof lang !== 'undefined' && lang === 'fr') ? fr : en;
  const T2 = (p) => (Array.isArray(p) ? L(p[0], p[1]) : p);
  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  // slide: { t, b: narrated bullet points, table: { head, rows, src, st }, tool, q: check question }
  const TB = (head, rows, src, st) => ({ head, rows, src, st: st || 'verify' });

  const COURSES = {
    UT: { icon: '📟', name: ['Ultrasonic testing of welds — professional', 'Contrôle ultrasonore des soudures — professionnel'], codes: 'ASME V Art. 4 · ASME VIII App. 12 · ASME B31.3 · ISO 17640 · ISO 11666 · ISO 9712', slides: [
      { t: ['Which code applies?', 'Quel code s’applique ?'], b: [['The construction code and the contract choose the rules. ASME work: ASME Section V Article 4 says how to examine, and the construction code, such as Section VIII or B31.3, says how much and what is acceptable.', 'Le code de construction et le contrat fixent les règles. En ASME : la section V article 4 dit comment contrôler, et le code de construction, comme la section VIII ou la B31.3, dit combien et ce qui est acceptable.'], ['ISO work: ISO 17640 gives the technique and testing levels, and ISO 11666 gives the acceptance levels, linked to the weld quality levels of ISO 5817.', 'En ISO : l’ISO 17640 donne la technique et les niveaux de contrôle, et l’ISO 11666 donne les niveaux d’acceptation, liés aux niveaux de qualité de l’ISO 5817.'], ['Never mix the two systems: blocks, reference levels and criteria belong together. A written procedure, approved by a Level 3, fixes all of it.', 'Ne mélangez jamais les deux systèmes : blocs, niveaux de référence et critères vont ensemble. Une procédure écrite, approuvée par un niveau 3, fixe tout cela.']] },
      { t: ['Calibration blocks you need', 'Les blocs d’étalonnage nécessaires'], b: [['You need two kinds of block. A standard block, IIW V1 or ISO 2400, or the V2 miniature block, ISO 7963, sets the range, the probe index and the real beam angle.', 'Il faut deux types de blocs. Un bloc standard, IIW V1 ou ISO 2400, ou le bloc V2 miniature, ISO 7963, règle la base de temps, le point d’émergence et l’angle réel.'], ['A basic calibration block, with side-drilled holes, sets the sensitivity and the DAC. It must represent the job: same material specification or P-number group, and same heat treatment.', 'Un bloc de base, à trous génératrices, règle la sensibilité et la DAC. Il doit représenter le travail : même spécification de matériau ou groupe P-number, et même traitement thermique.'], ['The thickness of the basic block depends on the weld thickness, as in this table.', 'L’épaisseur du bloc de base dépend de l’épaisseur de la soudure, comme dans ce tableau.']],
        table: TB([['Weld thickness t', 'Épaisseur de soudure e'], ['Block thickness T', 'Épaisseur du bloc T'], ['Side-drilled hole Ø', 'Trou génératrice Ø']], [['≤ 25 mm (1 in)', ['19 mm (3/4 in) or t', '19 mm (3/4 in) ou e'], '2.5 mm (3/32 in)'], ['25–50 mm (1–2 in)', ['38 mm (1½ in) or t', '38 mm (1½ in) ou e'], '3 mm (1/8 in)'], ['50–100 mm (2–4 in)', ['75 mm (3 in) or t', '75 mm (3 in) ou e'], '5 mm (3/16 in)'], ['> 100 mm (4 in)', ['t ± 25 mm (1 in)', 'e ± 25 mm (1 in)'], ['+1.5 mm (1/16 in) per extra 50 mm (2 in)', '+1,5 mm (1/16 in) par 50 mm (2 in) de plus']]], 'ASME V Art. 4, Fig. T-434.2.1 (non-piping)', 'checked'), tool: 'block' },
      { t: ['Inside the basic block', 'Dans le bloc de base'], b: [['Holes are drilled at one quarter, one half and three quarters of T. Blocks under 19 millimetres need only the half-T hole and surface notches.', 'Les trous sont percés à un quart, une moitié et trois quarts de T. Les blocs de moins de 19 millimètres n’exigent que le trou à T/2 et des entailles de surface.'], ['Hole tolerance is about plus or minus 0.8 millimetres, a thirty-second of an inch. Surface notches check near-surface and far-surface sensitivity.', 'La tolérance des trous est d’environ plus ou moins 0,8 millimètre, soit 1/32 de pouce. Les entailles de surface vérifient la sensibilité près des surfaces.'], ['Curved parts: below about 500 millimetres diameter, the block must be curved too, within 0.9 to 1.5 times the part diameter. Pipe uses the notch block of T-434.3. Check the article in your edition.', 'Pièces courbes : en dessous d’environ 500 millimètres de diamètre, le bloc doit aussi être courbe, de 0,9 à 1,5 fois le diamètre de la pièce. Les tubes utilisent le bloc à entailles de T-434.3. Vérifiez l’article dans votre édition.']],
        table: TB([['Item', 'Élément'], ['Requirement (summary)', 'Exigence (résumé)']], [[['Block < 19 mm', 'Bloc < 19 mm'], ['½T hole + notches', 'Trou ½T + entailles']], [['Hole tolerance', 'Tolérance des trous'], '± 1/32 in'], [['Curved surface', 'Surface courbe'], ['0.9–1.5 × part Ø when Ø ≤ 500 mm', '0,9–1,5 × Ø pièce si Ø ≤ 500 mm']]], 'ASME V Art. 4, T-434', 'verify') },
      { t: ['Calibration sequence (ASME)', 'Séquence d’étalonnage (ASME)'], b: [['First the range: use the V1 or V2 radius echoes to set the screen. Then find the index point and measure the real angle on the block.', 'D’abord la base de temps : utilisez les échos des rayons du V1 ou V2. Puis trouvez le point d’émergence et mesurez l’angle réel sur le bloc.'], ['Then the DAC: peak the first hole at about 80 percent of full screen height. That gain is the primary reference level. Without changing the gain, mark the other holes and draw the curve.', 'Puis la DAC : maximisez le premier trou vers 80 pour cent de la hauteur d’écran. Ce gain est le niveau de référence principal. Sans changer le gain, marquez les autres trous et tracez la courbe.'], ['Scan at twice the primary reference level, that is at least 6 decibels more, with 10 percent overlap and no faster than 150 millimetres per second.', 'Balayez à deux fois le niveau de référence principal, soit au moins 6 décibels de plus, avec 10 pour cent de recouvrement et sans dépasser 150 millimètres par seconde.'], ['Confirm the calibration at the start and the end of the work and when something changes. If the sweep moved more than 10 percent, or the level dropped by 20 percent or 2 decibels, void and re-examine according to the article.', 'Confirmez l’étalonnage au début et à la fin du travail et à tout changement. Si la base de temps a bougé de plus de 10 pour cent, ou si le niveau a baissé de 20 pour cent ou 2 décibels, annulez et recontrôlez selon l’article.']],
        table: TB([['Parameter', 'Paramètre'], ['Value (summary)', 'Valeur (résumé)']], [[['Scanning gain', 'Gain de balayage'], ['≥ 2 × primary reference level', '≥ 2 × niveau de référence principal']], [['Overlap', 'Recouvrement'], ['≥ 10 % of transducer', '≥ 10 % du traducteur']], [['Scan speed', 'Vitesse'], ['≤ 150 mm/s (6 in/s)', '≤ 150 mm/s (6 in/s)']], [['Calibration confirmation', 'Confirmation'], ['sweep 10 % · amplitude 20 % or 2 dB', 'base de temps 10 % · amplitude 20 % ou 2 dB']]], 'ASME V Art. 4, T-46x / T-47x', 'verify'),
        q: { q: ['A butt weld is 32 mm thick (non-piping, ASME). Which basic block?', 'Une soudure bout à bout fait 32 mm (hors tuyauterie, ASME). Quel bloc de base ?'], o: [['38 mm (or 32 mm), 3 mm holes', '38 mm (ou 32 mm), trous de 3 mm'], ['19 mm, 2.5 mm holes', '19 mm, trous de 2,5 mm'], ['75 mm, 5 mm holes', '75 mm, trous de 5 mm']], a: 0, why: ['25–50 mm uses T = 38 mm or the weld thickness, with 3 mm holes.', '25–50 mm utilise T = 38 mm ou l’épaisseur de soudure, avec des trous de 3 mm.'] } },
      { t: ['Acceptance: ASME VIII Appendix 12', 'Acceptation : ASME VIII annexe 12'], b: [['Investigate every imperfection producing a response above 20 percent of the reference level, to find its type and location.', 'Examinez toute imperfection donnant une réponse supérieure à 20 pour cent du niveau de référence, pour trouver son type et sa position.'], ['Cracks, lack of fusion and incomplete penetration are unacceptable, regardless of length.', 'Fissures, manques de fusion et manques de pénétration sont inacceptables, quelle que soit la longueur.'], ['Other imperfections are unacceptable if they exceed the reference level and are longer than the limit in this table.', 'Les autres imperfections sont inacceptables si elles dépassent le niveau de référence et sont plus longues que la limite de ce tableau.']],
        table: TB([['Thickness t', 'Épaisseur e'], ['Maximum length', 'Longueur maximale']], [['≤ 19 mm (3/4 in)', '6 mm (1/4 in)'], ['19–57 mm (3/4–2¼ in)', 't/3'], ['> 57 mm (2¼ in)', '19 mm (3/4 in)']], 'ASME VIII Div. 1, Mandatory App. 12', 'verify') },
      { t: ['Acceptance: ISO 11666', 'Acceptation : ISO 11666'], b: [['ISO 11666 covers full-penetration welds in ferritic steel from 8 to 100 millimetres, with two acceptance levels: AL 2 and AL 3, matching quality levels B and C of ISO 5817.', 'L’ISO 11666 couvre les soudures à pleine pénétration en acier ferritique de 8 à 100 millimètres, avec deux niveaux d’acceptation : AL 2 et AL 3, correspondant aux niveaux de qualité B et C de l’ISO 5817.'], ['H0 is the reference level. With technique 1 it comes from a 3 millimetre side-drilled hole. The maximum allowed height depends on thickness and on indication length, and evaluation starts 4 decibels below the recording level.', 'H0 est le niveau de référence. Avec la technique 1, il provient d’un trou génératrice de 3 millimètres. La hauteur maximale dépend de l’épaisseur et de la longueur de l’indication, et l’évaluation commence 4 décibels sous le niveau d’enregistrement.'], ['This table is from training knowledge. The standard is paid and a new edition is being prepared, so check every number in your copy before use.', 'Ce tableau vient de connaissances de formation. La norme est payante et une nouvelle édition est en préparation : vérifiez chaque chiffre dans votre exemplaire avant usage.']],
        table: TB([['Level, thickness', 'Niveau, épaisseur'], ['Length l', 'Longueur l'], ['Maximum height', 'Hauteur maximale']], [['AL 2 · 8–15 mm', 'l ≤ t', 'H0 − 4 dB'], ['AL 2 · 8–15 mm', 'l > t', 'H0 − 10 dB'], ['AL 2 · 15–100 mm', 'l ≤ 0.5 t', 'H0'], ['AL 2 · 15–100 mm', 'l > 0.5 t', 'H0 − 6 dB'], ['AL 3 · 8–15 mm', 'l ≤ t', 'H0'], ['AL 3 · 8–15 mm', 'l > t', 'H0 − 6 dB'], ['AL 3 · 15–100 mm', 'l ≤ 0.5 t', 'H0 + 4 dB'], ['AL 3 · 15–100 mm', 'l > 0.5 t', 'H0 − 2 dB']], 'ISO 11666, technique 1 (with ISO 17640)', 'verify') },
      { t: ['Personnel and the report', 'Personnel et rapport'], b: [['ISO 9712 certifies Levels 1, 2 and 3 through a central body. It requires a near-vision test, Jaeger 1 at 30 centimetres or more, every year, with renewal at 5 years and recertification at 10. In the ASME world, employers often qualify people under SNT-TC-1A or CP-189.', 'L’ISO 9712 certifie les niveaux 1, 2 et 3 par un organisme central. Elle exige un test de vision de près, Jaeger 1 à 30 centimètres ou plus, chaque année, avec renouvellement à 5 ans et recertification à 10. En ASME, les employeurs qualifient souvent selon la SNT-TC-1A ou la CP-189.'], ['A report must allow someone else to repeat the work: procedure and revision, instrument and probes with serial numbers, blocks, couplant, surface, scan plan, each indication with position, length and amplitude, your decision, name, level and date.', 'Un rapport doit permettre à un autre de refaire le travail : procédure et révision, appareil et traducteurs avec numéros de série, blocs, couplant, surface, plan de balayage, chaque indication avec position, longueur et amplitude, votre décision, nom, niveau et date.']] }
    ] },
    RT: { icon: '🎞', name: ['Radiographic testing — professional', 'Radiographie — professionnel'], codes: 'ASME V Art. 2 · ASME VIII UW-51/UW-52, App. 4 · ISO 17636 · ISO 10675-1 · ISO 19232', slides: [
      { t: ['Technique and image quality', 'Technique et qualité d’image'], b: [['ASME Section V Article 2 sets the technique. ISO 17636 part 1 for film uses class A, basic, and class B, improved. ISO 19232 defines the indicators.', 'L’ASME section V article 2 fixe la technique. L’ISO 17636 partie 1 pour le film utilise la classe A, de base, et la classe B, améliorée. L’ISO 19232 définit les indicateurs.'], ['Geometric unsharpness is calculated as focal size times object-to-film distance, divided by source-to-object distance. Keep the film close and the source far.', 'Le flou géométrique se calcule comme taille du foyer fois distance objet-film, divisée par distance source-objet. Gardez le film proche et la source loin.'], ['Check for backscatter with a lead letter B on the back of the cassette: a light B on the film means too much scatter, and the film is rejected.', 'Contrôlez le rétrodiffusé avec une lettre B en plomb au dos de la cassette : un B clair sur le film signifie trop de diffusé, et le film est refusé.']] },
      { t: ['Density limits', 'Limites de densité'], b: [['Measure density through the body of the IQI or next to the essential wire, with a calibrated densitometer.', 'Mesurez la densité à travers le corps de l’IQI ou à côté du fil essentiel, avec un densitomètre étalonné.'], ['In the area of interest the density may vary only from minus 15 to plus 30 percent of that value, and must stay in the absolute limits below. Otherwise add an IQI.', 'Dans la zone d’intérêt, la densité ne peut varier que de moins 15 à plus 30 pour cent de cette valeur, et doit rester dans les limites absolues ci-dessous. Sinon, ajoutez un IQI.']],
        table: TB([['Case', 'Cas'], ['Density', 'Densité']], [[['X-ray, single film', 'Rayons X, film simple'], '1.8 – 4.0'], [['Gamma, single film', 'Gamma, film simple'], '2.0 – 4.0'], [['Variation around the IQI', 'Variation autour de l’IQI'], '−15 % / +30 %']], 'ASME V Art. 2, T-282', 'verify') },
      { t: ['Choosing the IQI', 'Choisir l’IQI'], b: [['IQI thickness is based on the nominal single-wall thickness plus the allowed reinforcement. A backing strip is not counted.', 'L’IQI se base sur l’épaisseur nominale d’une paroi plus le renfort autorisé. Le support envers n’est pas compté.'], ['Place it on the source side when you can. On the film side, mark it with a lead F and use the film-side table of your code.', 'Placez-le côté source si possible. Côté film, marquez-le avec un F en plomb et utilisez le tableau côté film du code.']],
        table: TB([['Thickness (mm)', 'Épaisseur (mm)'], ['Hole type', 'Type à trous'], ['Essential wire', 'Fil essentiel']], [['≤ 6.4', '12', '5'], ['6.4–9.5', '15', '6'], ['9.5–12.7', '17', '7'], ['12.7–19', '20', '8'], ['19–25.4', '25', '9'], ['25.4–38', '30', '10'], ['38–50.8', '35', '11'], ['50.8–63.5', '40', '12'], ['63.5–101.6', '50', '13']], 'ASME V Art. 2, Table T-276 (source side)', 'verify'), tool: 'iqi' },
      { t: ['Acceptance: ASME VIII UW-51', 'Acceptation : ASME VIII UW-51'], b: [['For full radiography under UW-51: any crack, lack of fusion or incomplete penetration is unacceptable.', 'Pour la radiographie totale selon UW-51 : toute fissure, tout manque de fusion ou de pénétration est inacceptable.'], ['Elongated indications are limited in length as in the table. Aligned groups are limited too, and rounded indications are judged with the charts of Appendix 4.', 'Les indications allongées sont limitées en longueur comme dans le tableau. Les groupes alignés sont aussi limités, et les indications arrondies se jugent avec les abaques de l’annexe 4.'], ['Spot radiography, UW-52, has its own, wider rules and a retest rule: two more spots if the first one fails.', 'La radiographie par sondage, UW-52, a ses propres règles, plus larges, et une règle de reprise : deux autres sondages si le premier échoue.']],
        table: TB([['Thickness t', 'Épaisseur e'], ['Max. elongated length', 'Longueur allongée max.']], [['≤ 19 mm', '6 mm'], ['19–57 mm', 't/3'], ['> 57 mm', '19 mm']], 'ASME VIII Div. 1, UW-51(b)', 'verify') },
      { t: ['Radiation safety', 'Radioprotection'], b: [['Time, distance and shielding are your three protections. Dose follows the inverse square law: twice as far means four times less.', 'Temps, distance et écran sont vos trois protections. La dose suit la loi de l’inverse du carré : deux fois plus loin signifie quatre fois moins.'], ['Always confirm with a calibrated survey meter that the source is back in its container, wear your dosimeter, and set up a controlled zone. National radiation law applies: in Algeria, follow the competent authority and your company’s licence.', 'Confirmez toujours au radiamètre étalonné que la source est rentrée, portez votre dosimètre et balisez une zone contrôlée. La loi nationale s’applique : en Algérie, suivez l’autorité compétente et l’autorisation de votre entreprise.']],
        q: { q: ['Single film, Ir-192. The density next to the essential wire is 2.5. Is a density of 3.4 in the weld allowed?', 'Film simple, Ir-192. La densité à côté du fil essentiel est 2,5. Une densité de 3,4 dans la soudure est-elle admise ?'], o: [['No: the limit is 2.5 × 1.30 = 3.25', 'Non : la limite est 2,5 × 1,30 = 3,25'], ['Yes: it is below 4.0', 'Oui : c’est sous 4,0'], ['Yes: gamma has no limit', 'Oui : le gamma n’a pas de limite']], a: 0, why: ['Both limits apply: the +30 % variation and the absolute range.', 'Les deux limites s’appliquent : la variation de +30 % et la plage absolue.'] } }
    ] },
    MT: { icon: '🧲', name: ['Magnetic particle testing — professional', 'Magnétoscopie — professionnel'], codes: 'ASME V Art. 7 · ASME VIII App. 6 · ISO 17638 · ISO 23278', slides: [
      { t: ['Technique requirements', 'Exigences de technique'], b: [['MT works only on ferromagnetic materials and finds surface and near-surface flaws. Yokes must be checked for lifting power at the maximum pole spacing you will use.', 'La MT ne fonctionne que sur matériaux ferromagnétiques et trouve les défauts débouchants et sous-jacents. La force portante des yokes doit être vérifiée à l’écartement maximal utilisé.'], ['Examine each area in two directions, about 90 degrees apart, with overlap, because a flaw parallel to the field does not show.', 'Contrôlez chaque zone dans deux directions à environ 90 degrés, avec recouvrement, car un défaut parallèle au champ n’apparaît pas.'], ['AC is best for surface cracks. DC gives more depth. Check field direction with a pie gauge or shims, and light with a meter.', 'Le courant alternatif est le meilleur pour les fissures débouchantes. Le continu pénètre plus. Vérifiez la direction du champ avec un indicateur et l’éclairage avec un luxmètre.']],
        table: TB([['Check', 'Contrôle'], ['Value', 'Valeur']], [[['AC yoke lifting power', 'Force portante yoke CA'], '≥ 4.5 kg (10 lb)'], [['DC / permanent yoke', 'Yoke CC / permanent'], '≥ 18 kg (40 lb)']], 'ASME V Art. 7, T-762', 'checked') },
      { t: ['Lighting and particles', 'Éclairage et particules'], b: [['Visible particles need at least 1000 lux on the surface. Fluorescent particles need UV-A of at least 1000 microwatts per square centimetre, in a dark area, after your eyes adapt for about 5 minutes.', 'Les particules visibles exigent au moins 1000 lux sur la surface. Les particules fluorescentes exigent des UV-A d’au moins 1000 microwatts par centimètre carré, dans l’obscurité, après environ 5 minutes d’adaptation des yeux.'], ['Check the suspension concentration of wet baths with a settling test, and do not exceed the temperature allowed by the particle supplier.', 'Vérifiez la concentration des bains par un test de décantation et ne dépassez pas la température admise par le fournisseur.']],
        table: TB([['Item', 'Élément'], ['Minimum', 'Minimum']], [[['Visible light', 'Lumière visible'], '1000 lx'], [['UV-A at surface', 'UV-A en surface'], '1000 µW/cm²'], [['Dark adaptation', 'Adaptation obscurité'], ['≈ 5 min', '≈ 5 min']]], 'ASME V Art. 6/7 (verify article)', 'verify') },
      { t: ['Acceptance: ASME VIII Appendix 6', 'Acceptation : ASME VIII annexe 6'], b: [['Only indications larger than 1.5 millimetres, a sixteenth of an inch, are relevant. Linear means longer than three times the width.', 'Seules les indications de plus de 1,5 millimètre, 1/16 de pouce, sont pertinentes. Linéaire signifie plus long que trois fois la largeur.'], ['These are unacceptable: relevant linear indications, relevant rounded indications larger than 5 millimetres, and four or more relevant rounded indications in a line, separated by 1.5 millimetres or less.', 'Sont inacceptables : les indications linéaires pertinentes, les arrondies pertinentes de plus de 5 millimètres, et quatre arrondies pertinentes ou plus alignées, séparées de 1,5 millimètre ou moins.'], ['Under ISO, ISO 23278 gives acceptance levels 1, 2 and 3 instead. Remove the magnetism and clean the part if required, then record.', 'En ISO, l’ISO 23278 donne à la place les niveaux d’acceptation 1, 2 et 3. Désaimantez et nettoyez si exigé, puis consignez.']],
        table: TB([['Indication', 'Indication'], ['Decision', 'Décision']], [[['Relevant linear', 'Linéaire pertinente'], ['Reject', 'Refus']], [['Rounded > 5 mm (3/16 in)', 'Arrondie > 5 mm (3/16 in)'], ['Reject', 'Refus']], [['≥ 4 rounded in line, ≤ 1.5 mm apart', '≥ 4 arrondies alignées, ≤ 1,5 mm'], ['Reject', 'Refus']]], 'ASME VIII Div. 1, App. 6-4', 'verify'),
        q: { q: ['A 4 mm long, 1 mm wide relevant indication under App. 6?', 'Une indication pertinente de 4 mm sur 1 mm selon l’annexe 6 ?'], o: [['Linear: reject', 'Linéaire : refus'], ['Rounded: accept', 'Arrondie : acceptée'], ['Not relevant', 'Non pertinente']], a: 0, why: ['4 > 3 × 1, so it is linear, and relevant linear indications are unacceptable.', '4 > 3 × 1 : elle est linéaire, et les indications linéaires pertinentes sont inacceptables.'] } }
    ] },
    PT: { icon: '🧪', name: ['Penetrant testing — professional', 'Ressuage — professionnel'], codes: 'ASME V Art. 6 · ASME VIII App. 8 · ISO 3452 · ISO 23277', slides: [
      { t: ['Process parameters', 'Paramètres du procédé'], b: [['Use a family of compatible products. On stainless steel and nickel alloys, products must be certified for low halogens and sulfur.', 'Utilisez une famille de produits compatibles. Sur inox et alliages de nickel, les produits doivent être certifiés à faible teneur en halogènes et soufre.'], ['Standard temperature range is 10 to 52 degrees Celsius. Outside it, the procedure must be qualified for that temperature.', 'La plage standard est de 10 à 52 degrés Celsius. En dehors, la procédure doit être qualifiée pour cette température.'], ['Minimum dwell times come from Table T-672 and depend on the material and flaw type, commonly 5 minutes for welds. Developing runs from 10 to 60 minutes, starting when the developer dries.', 'Les temps de pénétration minimaux viennent du tableau T-672 et dépendent du matériau et du type de défaut, couramment 5 minutes pour les soudures. La révélation dure de 10 à 60 minutes, à partir du séchage du révélateur.'], ['Solvent-removable: wipe with a dry cloth, then a cloth lightly moistened. Never spray remover directly on the surface. Under ISO, follow ISO 3452 and its dwell and classification tables.', 'Éliminable au solvant : essuyez au chiffon sec, puis au chiffon légèrement imbibé. Ne pulvérisez jamais le nettoyant sur la surface. En ISO, suivez l’ISO 3452 et ses tableaux.']],
        table: TB([['Parameter', 'Paramètre'], ['Common value', 'Valeur courante']], [[['Temperature', 'Température'], '10–52 °C'], [['Dwell, welds', 'Pénétration, soudures'], ['≥ 5 min (see T-672)', '≥ 5 min (voir T-672)']], [['Development', 'Révélation'], '10–60 min'], [['Visible light', 'Lumière visible'], '≥ 1000 lx']], 'ASME V Art. 6, T-65x, T-672, T-676', 'verify') },
      { t: ['Acceptance: ASME VIII Appendix 8', 'Acceptation : ASME VIII annexe 8'], b: [['Same logic as MT: only indications over 1.5 millimetres are relevant. Linear indications are unacceptable, rounded ones over 5 millimetres are unacceptable, and four or more in line, 1.5 millimetres or less apart, are unacceptable.', 'Même logique qu’en MT : seules les indications de plus de 1,5 millimètre sont pertinentes. Les linéaires sont inacceptables, les arrondies de plus de 5 millimètres aussi, ainsi que quatre ou plus alignées à 1,5 millimètre ou moins.'], ['Remember that bleed-out grows with time: the indication size is not the flaw size. Under ISO, use ISO 23277 levels. Re-examine after any repair, then clean off all residues.', 'N’oubliez pas que le ressuage s’étale avec le temps : la taille de l’indication n’est pas celle du défaut. En ISO, utilisez les niveaux de l’ISO 23277. Recontrôlez après réparation, puis retirez tous les résidus.']],
        table: TB([['Indication', 'Indication'], ['Decision', 'Décision']], [[['Relevant linear (l > 3w)', 'Linéaire pertinente (l > 3l)'], ['Reject', 'Refus']], [['Rounded > 5 mm', 'Arrondie > 5 mm'], ['Reject', 'Refus']], [['≥ 4 rounded in line, ≤ 1.5 mm apart', '≥ 4 arrondies alignées, ≤ 1,5 mm'], ['Reject', 'Refus']]], 'ASME VIII Div. 1, App. 8-4', 'verify') }
    ] },
    VT: { icon: '👁', name: ['Visual testing and welding — professional', 'Contrôle visuel et soudage — professionnel'], codes: 'ASME V Art. 9 · ASME VIII UW-35 · ASME B31.3 · ISO 17637 · ISO 5817 · ASME IX', slides: [
      { t: ['Viewing requirements', 'Conditions d’observation'], b: [['Direct visual examination: eye within about 600 millimetres of the surface, at an angle of at least 30 degrees, and at least 1000 lux on the surface.', 'Contrôle visuel direct : œil à moins d’environ 600 millimètres de la surface, angle d’au moins 30 degrés, et au moins 1000 lux sur la surface.'], ['ISO 17637 uses 350 lux as the minimum and recommends 500. Remote aids, such as borescopes, must show equivalent resolution.', 'L’ISO 17637 prend 350 lux comme minimum et recommande 500. Les aides à distance, comme les endoscopes, doivent offrir une résolution équivalente.'], ['Check before welding, during welding and after welding. Many defects are prevented by checking the fit-up, cleanliness, WPS and welder qualification, under ASME Section IX or ISO 9606.', 'Contrôlez avant, pendant et après le soudage. Beaucoup de défauts s’évitent en vérifiant l’accostage, la propreté, le DMOS et la qualification du soudeur, selon l’ASME section IX ou l’ISO 9606.']],
        table: TB([['Requirement', 'Exigence'], ['ASME V Art. 9', 'ISO 17637']], [[['Light', 'Lumière'], '≥ 1000 lx', '≥ 350 lx (500 rec.)'], [['Distance', 'Distance'], '≤ 600 mm', '≤ 600 mm'], [['Angle', 'Angle'], '≥ 30°', '≥ 30°']], 'ASME V T-952; ISO 17637', 'verify') },
      { t: ['Surface criteria', 'Critères de surface'], b: [['Each code has its own limits. ASME VIII UW-35 limits undercut to the lesser of 0.8 millimetres or 10 percent of thickness. Reinforcement limits depend on thickness.', 'Chaque code a ses limites. L’ASME VIII UW-35 limite le caniveau à la plus petite valeur entre 0,8 millimètre et 10 pour cent de l’épaisseur. Le renfort dépend de l’épaisseur.'], ['ISO 5817 has three quality levels: B is stringent, C intermediate and D moderate. Cracks are never permitted.', 'L’ISO 5817 a trois niveaux de qualité : B sévère, C intermédiaire et D modéré. Les fissures ne sont jamais admises.'], ['B31.3 has its own Table 341.3.2 with limits by fluid service. Normal fluid and severe cyclic differ, so read the right column.', 'La B31.3 a son propre tableau 341.3.2, avec des limites par service. Fluide normal et cyclique sévère diffèrent : lisez la bonne colonne.']],
        table: TB([['Continuous undercut', 'Caniveau continu'], ['Limit', 'Limite']], [['ASME VIII UW-35', ['≤ lesser of 0.8 mm, 0.1 t', '≤ plus petit de 0,8 mm, 0,1 e']], ['ISO 5817 B', '≤ 0.05 t, max 0.5 mm'], ['ISO 5817 C', '≤ 0.1 t, max 0.5 mm'], ['ISO 5817 D', '≤ 0.2 t, max 1 mm']], 'ASME VIII UW-35; ISO 5817 (t > 3 mm)', 'verify') }
    ] },
    APVG: { icon: '🛢', name: ['Pressure equipment inspection — professional', 'Inspection des appareils à pression — professionnel'], codes: 'ASME VIII · API 510 · API 570 · API 576 · PED 2014/68/EU · National regulation', slides: [
      { t: ['The legal framework comes first', 'Le cadre légal d’abord'], b: [['Regulation decides intervals, witnesses and who may inspect. In Algeria, gas pressure equipment comes under Executive Decree 90-245 of 18 August 1990. CYCLOPS does not state its intervals because the text could not be consulted here: use the official text and AQCS procedures.', 'La réglementation fixe les intervalles, les témoins et qui peut inspecter. En Algérie, les appareils à pression de gaz relèvent du décret exécutif 90-245 du 18 août 1990. CYCLOPS n’en donne pas les intervalles car le texte n’a pas pu être consulté ici : utilisez le texte officiel et les procédures AQCS.'], ['ASME VIII is a construction code. API 510 for vessels and API 570 for piping cover inspection in service. API 576 covers relief devices.', 'L’ASME VIII est un code de construction. L’API 510 pour les appareils et l’API 570 pour la tuyauterie couvrent l’inspection en service. L’API 576 couvre les organes de sécurité.']] },
      { t: ['Pressure tests', 'Épreuves de pression'], b: [['New ASME VIII vessels are normally tested hydrostatically at 1.3 times the MAWP, corrected by the stress ratio. Pneumatic tests are 1.1 times, and need extra precautions because of stored energy.', 'Les appareils neufs ASME VIII sont normalement éprouvés à l’eau à 1,3 fois la PMS, corrigée par le rapport de contraintes. Les épreuves pneumatiques sont à 1,1 fois, avec précautions renforcées à cause de l’énergie stockée.'], ['Inspect at no less than the test pressure divided by 1.3. Use a gauge with a range of about twice the test pressure, between 1.5 and 4 times, and vent all air first.', 'Inspectez à une pression d’au moins la pression d’épreuve divisée par 1,3. Utilisez un manomètre d’échelle d’environ deux fois la pression d’épreuve, entre 1,5 et 4 fois, et purgez tout l’air d’abord.']],
        table: TB([['Test', 'Épreuve'], ['Pressure (summary)', 'Pression (résumé)']], [[['Hydrostatic, ASME VIII UG-99', 'Hydraulique, ASME VIII UG-99'], '1.3 × MAWP × stress ratio'], [['Pneumatic, UG-100', 'Pneumatique, UG-100'], '1.1 × MAWP × stress ratio'], [['PED hydrostatic', 'Hydraulique DESP'], ['max (1.25 PS·ratio ; 1.43 PS)', 'max (1,25 PS·rapport ; 1,43 PS)']]], 'ASME VIII Div. 1 UG-99/UG-100; PED Annex I', 'verify') },
      { t: ['Corrosion and intervals', 'Corrosion et intervalles'], b: [['Corrosion rate equals thickness lost divided by years. Remaining life equals current thickness minus required thickness, divided by the rate. Use the worst measuring point and compare long-term and short-term rates.', 'La vitesse de corrosion égale l’épaisseur perdue divisée par les années. La durée de vie égale l’épaisseur actuelle moins l’épaisseur requise, divisée par la vitesse. Prenez le pire point et comparez vitesses long terme et court terme.'], ['API 510 sets the internal or on-stream interval at the lesser of half the remaining life or 10 years, and has limits for external visual inspection and relief valves. Regulation can be stricter, and then regulation wins.', 'L’API 510 fixe l’intervalle interne ou en service au plus petit de la moitié de la durée de vie ou de 10 ans, avec des limites pour le visuel externe et les soupapes. La réglementation peut être plus stricte, et elle l’emporte alors.']],
        table: TB([['API 510 item', 'Élément API 510'], ['Maximum interval (summary)', 'Intervalle maximal (résumé)']], [[['Internal / on-stream', 'Interne / en service'], ['lesser of ½ remaining life, 10 years', 'plus petit de ½ durée de vie, 10 ans']], [['External visual', 'Visuel externe'], ['lesser of 5 years, internal interval', 'plus petit de 5 ans, intervalle interne']], [['Relief valves', 'Soupapes'], ['5 years, up to 10 if clean service', '5 ans, jusqu’à 10 si service propre']]], 'API 510; API 576', 'verify'),
        q: { q: ['Remaining life is 12 years. Maximum internal interval under API 510?', 'La durée de vie restante est de 12 ans. Intervalle interne maximal selon l’API 510 ?'], o: [['6 years', '6 ans'], ['10 years', '10 ans'], ['12 years', '12 ans']], a: 0, why: ['Half of 12 is 6, which is less than 10 years.', 'La moitié de 12 est 6, inférieur à 10 ans.'] } }
    ] },
    APL: { icon: '🏗', name: ['Lifting equipment inspection — professional', 'Inspection des appareils de levage — professionnel'], codes: 'ASME B30.2 · B30.9 · B30.10 · ISO 4309 · ISO 9927 · EN 15011 · Machinery Directive', slides: [
      { t: ['Examinations and load tests', 'Examens et essais de charge'], b: [['Combine frequent checks by the operator, periodic examinations by a competent person and tests after installation or major repair. Regulation sets the periods: check the national text and AQCS procedures.', 'Combinez les contrôles fréquents par l’opérateur, les examens périodiques par une personne compétente et les essais après installation ou grosse réparation. La réglementation fixe les périodes : vérifiez le texte national et les procédures AQCS.'], ['Under ASME B30.2, test loads are normally between 100 and 125 percent of the rated load, and not more than 125 percent unless the manufacturer agrees.', 'Selon l’ASME B30.2, les charges d’essai sont normalement entre 100 et 125 pour cent de la charge nominale, et pas plus de 125 pour cent sans accord du fabricant.'], ['The European Machinery Directive uses a static test of at least 1.25 and a dynamic test of at least 1.1 times the maximum working load. Always use certified weights and an exclusion zone.', 'La directive Machines européenne utilise un essai statique d’au moins 1,25 et dynamique d’au moins 1,1 fois la charge maximale. Utilisez toujours des masses certifiées et une zone d’exclusion.']],
        table: TB([['Reference', 'Référence'], ['Test load (summary)', 'Charge d’essai (résumé)']], [['ASME B30.2', ['100–125 % rated load', '100–125 % charge nominale']], [['Machinery Dir. 2006/42/EC, static', 'Directive Machines, statique'], '≥ 1.25 × WLL'], [['Machinery Dir., dynamic', 'Directive Machines, dynamique'], '≥ 1.1 × WLL']], 'ASME B30.2 cross-checked via OSHA and summaries; Directive 2006/42/EC Annex I values from training knowledge: verify', 'verify') },
      { t: ['Hooks and rigging', 'Crochets et élingage'], b: [['Remove a hook from service for a crack, a throat opening increase beyond the limit, excessive wear, a twist, or a damaged latch. Never straighten or heat a hook.', 'Retirez un crochet du service pour une fissure, une ouverture au-delà de la limite, une usure excessive, une torsion ou un linguet abîmé. Ne redressez ni ne chauffez jamais un crochet.'], ['Sling leg tension equals the load divided by the number of legs and the cosine of the angle from vertical. ASME B30.9 and the sling tag give the working load at each angle.', 'L’effort dans un brin égale la charge divisée par le nombre de brins et le cosinus de l’angle à la verticale. L’ASME B30.9 et l’étiquette donnent la charge à chaque angle.']],
        table: TB([['Hook defect', 'Défaut du crochet'], ['Removal limit (summary)', 'Limite de retrait (résumé)']], [[['Throat opening', 'Ouverture'], ['+5 %, not more than 6 mm', '+5 %, au plus 6 mm']], [['Wear', 'Usure'], ['10 % of the original section', '10 % de la section d’origine']], [['Twist', 'Torsion'], ['10° from the hook plane', '10° du plan du crochet']]], 'ASME B30.10 — check your edition', 'verify') },
      { t: ['Wire ropes', 'Câbles'], b: [['ISO 4309 is the reference for discard. It looks at visible broken wires, decrease in diameter, corrosion, deformation and damage. Inspect where the rope suffers: at the drum, the sheaves and the terminations.', 'L’ISO 4309 est la référence pour la dépose. Elle examine les fils cassés visibles, la diminution de diamètre, la corrosion, la déformation et les dommages. Contrôlez là où le câble souffre : tambour, poulies et extrémités.'], ['Broken-wire limits depend on rope class and crane group. Diameter is judged against the reference diameter measured on the new rope, with limits that depend on construction. Read the numbers in your edition and the rope manufacturer’s data. CYCLOPS does not state them because they could not be checked.', 'Les limites de fils cassés dépendent de la classe du câble et du groupe de l’appareil. Le diamètre se juge par rapport au diamètre de référence mesuré sur le câble neuf, avec des limites selon la construction. Lisez les chiffres dans votre édition et les données du fabricant. CYCLOPS ne les donne pas car ils n’ont pas pu être vérifiés.']] }
    ] },
    APE: { icon: '⚡', name: ['Electrical installation inspection — professional', 'Vérification des installations électriques — professionnel'], codes: 'IEC 60364 · NF C 15-100 · IEC 61008 · NFPA 70B/NETA · National regulation', slides: [
      { t: ['Safety and order of tests', 'Sécurité et ordre des essais'], b: [['Lockout comes first. Identify, separate, lock, prove the tester, verify absence of voltage, and prove the tester again. Live work needs specific authorisation.', 'La consignation vient d’abord. Identifier, séparer, condamner, prouver le VAT, vérifier l’absence de tension, et reprouver le VAT. Le travail sous tension exige une habilitation spécifique.'], ['IEC 60364 part 6 orders the initial verification: visual inspection, protective conductor continuity, insulation resistance, then with power on, automatic disconnection, RCDs, polarity, phase sequence and function.', 'L’IEC 60364 partie 6 ordonne la vérification initiale : examen visuel, continuité des conducteurs de protection, isolement, puis sous tension, coupure automatique, différentiels, polarité, ordre des phases et fonctionnement.']] },
      { t: ['Insulation resistance', 'Résistance d’isolement'], b: [['Disconnect surge protectors and electronics first. Test between live conductors and earth at the voltage for the circuit. The values below are minimums, and a healthy circuit usually reads much higher.', 'Débranchez d’abord parafoudres et électronique. Testez entre conducteurs actifs et terre à la tension du circuit. Les valeurs ci-dessous sont des minimums, et un circuit sain indique souvent beaucoup plus.']],
        table: TB([['Circuit voltage', 'Tension du circuit'], ['Test voltage DC', 'Tension d’essai CC'], ['Minimum', 'Minimum']], [['SELV / PELV', '250 V', '0.5 MΩ'], ['≤ 500 V', '500 V', '1 MΩ'], ['> 500 V', '1000 V', '1 MΩ']], 'IEC 60364-6, Table 6.1', 'verify') },
      { t: ['Disconnection and RCDs', 'Coupure et différentiels'], b: [['The earth fault loop must disconnect fast enough. In TN systems the condition is Zs times Ia at or below U0. In TT systems with an RCD, the earth resistance times the RCD current must be at or below 50 volts.', 'La boucle de défaut doit couper assez vite. En schéma TN, la condition est Zs fois Ia inférieur ou égal à U0. En TT avec différentiel, la résistance de terre fois le courant du différentiel doit rester sous 50 volts.'], ['Test each general-type RCD with a tester: it should trip within 300 milliseconds at its rated current, and within 40 milliseconds at five times that current. The T button checks only the mechanism.', 'Testez chaque différentiel de type général : il doit déclencher en 300 millisecondes à son courant assigné, et en 40 millisecondes à cinq fois ce courant. Le bouton T vérifie seulement le mécanisme.']],
        table: TB([['Final circuit ≤ 32 A', 'Circuit terminal ≤ 32 A'], ['TN', 'TT']], [['120–230 V', '0.4 s', '0.2 s'], ['230–400 V', '0.2 s', '0.07 s'], [['General RCD, IΔn', 'DDR général, IΔn'], '≤ 300 ms', '≤ 300 ms'], [['General RCD, 5 × IΔn', 'DDR général, 5 × IΔn'], '≤ 40 ms', '≤ 40 ms']], 'IEC 60364-4-41; IEC 61008', 'verify') },
      { t: ['Thermography and voltage drop', 'Thermographie et chute de tension'], b: [['Scan at a significant load and from a safe distance. Compare similar components under the same load. Report the temperature difference, the load, an image and the location. Correct faults only after isolation.', 'Scannez à une charge significative et à distance de sécurité. Comparez des composants similaires à la même charge. Consignez la différence de température, la charge, une image et l’emplacement. Corrigez seulement après consignation.'], ['Severity bands vary. A commonly used table from NETA is below, for comparisons between similar components. Voltage drop limits in NF C 15-100 are commonly 3 percent for lighting and 5 percent for other uses from a public supply. Confirm them in your edition.', 'Les classes de gravité varient. Un tableau courant de la NETA figure ci-dessous, pour les comparaisons entre composants similaires. Les limites de chute de tension de la NF C 15-100 sont couramment 3 pour cent pour l’éclairage et 5 pour cent pour les autres usages depuis un réseau public. Confirmez-les dans votre édition.']],
        table: TB([['ΔT, similar components', 'ΔT, composants similaires'], ['Suggested action', 'Action suggérée']], [['1–3 °C', ['Possible deficiency, investigate', 'Anomalie possible, à examiner']], ['4–15 °C', ['Probable deficiency, repair as time permits', 'Anomalie probable, réparer dès que possible']], ['> 15 °C', ['Major discrepancy, repair immediately', 'Anomalie majeure, réparer immédiatement']]], 'ANSI/NETA MTS / ATS', 'verify'),
        q: { q: ['A 30 mA RCD trips in 340 ms at 30 mA. Result?', 'Un DDR 30 mA déclenche en 340 ms à 30 mA. Résultat ?'], o: [['Fail: above 300 ms', 'Non conforme : au-delà de 300 ms'], ['Pass: below 400 ms', 'Conforme : sous 400 ms'], ['Pass: the T button works', 'Conforme : le bouton T fonctionne']], a: 0, why: ['A general-type RCD must trip within 300 ms at its rated residual current.', 'Un DDR de type général doit déclencher en 300 ms à son courant assigné.'] } }
    ] }
  };
  const ORDER = ['UT', 'RT', 'MT', 'PT', 'VT', 'APVG', 'APL', 'APE'];

  /* ---------- tools inside slides ---------- */
  function blockFor(t) {
    if (t <= 25) return { T: L(`19 mm or ${t} mm`, `19 mm ou ${t} mm`), d: '2.5 mm (3/32 in)' };
    if (t <= 50) return { T: L(`38 mm or ${t} mm`, `38 mm ou ${t} mm`), d: '3 mm (1/8 in)' };
    if (t === 75) return { T: '75 mm', d: '5 mm (3/16 in)' };
    if (t <= 100) return { T: L(`75 mm or ${t} mm`, `75 mm ou ${t} mm`), d: '5 mm (3/16 in)' };
    const extra = Math.ceil((t - 100) / 50), mm = 5 + extra * 1.5;
    return { T: `${t} ± 25 mm`, d: L(`${mm} mm (5 + 1.5 × ${extra})`, `${String(mm).replace('.', ',')} mm (5 + 1,5 × ${extra})`) };
  }
  const IQI = [[6.4, 12, 5], [9.5, 15, 6], [12.7, 17, 7], [19, 20, 8], [25.4, 25, 9], [38, 30, 10], [50.8, 35, 11], [63.5, 40, 12], [101.6, 50, 13]];
  const nf = (v, n) => L(Number(v).toFixed(n), Number(v).toFixed(n).replace('.', ','));
  const lenLimit = (t) => (t <= 19 ? 6 : t <= 57 ? t / 3 : 19);
  const ugLimit = (t) => (t < 50.8 ? 0.51 : t <= 76.2 ? 0.76 : t <= 101.6 ? 1.02 : 1.78);
  // { fields: [key, [en, fr], default, unit], run(values) → text }
  const TOOLS = {
    block: { f: [['t', ['Your weld thickness', 'Votre épaisseur de soudure'], 32, 'mm']], run: (v) => { const r = blockFor(v.t); return L(`Block: ${r.T} · holes Ø ${r.d}`, `Bloc : ${r.T} · trous Ø ${r.d}`); } },
    iqi: { f: [['t', ['Thickness for IQI (wall + allowed reinforcement)', 'Épaisseur pour l’IQI (paroi + renfort admis)'], 16, 'mm']], run: (v) => { const r = IQI.find((x) => v.t <= x[0]); return r ? L(`Hole type ${r[1]} · essential wire ${r[2]} (source side)`, `Type à trous ${r[1]} · fil essentiel ${r[2]} (côté source)`) : L('Above this table: use the full code table.', 'Au-delà de ce tableau : utilisez le tableau complet du code.'); } },
    near: { f: [['D', ['Crystal diameter D', 'Diamètre du cristal D'], 10, 'mm'], ['f', ['Frequency f', 'Fréquence f'], 4, 'MHz'], ['V', ['Velocity V', 'Vitesse V'], 5920, 'm/s']], run: (v) => { const lam = v.V / (v.f * 1000), N = v.D * v.D / (4 * lam), sn = 1.22 * lam / v.D; return L(`λ = ${nf(lam, 2)} mm · near field N = D² ÷ 4λ = ${nf(N, 1)} mm · beam half-angle to zero ≈ ${sn < 1 ? nf(Math.asin(sn) * 180 / Math.PI, 1) + '°' : '—'}`, `λ = ${nf(lam, 2)} mm · champ proche N = D² ÷ 4λ = ${nf(N, 1)} mm · demi-angle jusqu’au zéro ≈ ${sn < 1 ? nf(Math.asin(sn) * 180 / Math.PI, 1) + '°' : '—'}`); } },
    skip: { f: [['T', ['Thickness T', 'Épaisseur T'], 25, 'mm'], ['a', ['Probe angle', 'Angle du traducteur'], 60, '°']], run: (v) => { const k = v.T * Math.tan(v.a * Math.PI / 180), S = v.T / Math.cos(v.a * Math.PI / 180); return L(`Half skip ${nf(k, 1)} mm · full skip ${nf(2 * k, 1)} mm · sound path per leg ${nf(S, 1)} mm → set a range above ${nf(2 * S, 0)} mm`, `Demi-bond ${nf(k, 1)} mm · bond ${nf(2 * k, 1)} mm · parcours par branche ${nf(S, 1)} mm → réglez une plage supérieure à ${nf(2 * S, 0)} mm`); } },
    limit: { f: [['t', ['Thickness t', 'Épaisseur e'], 32, 'mm']], run: (v) => L(`Maximum length: ${nf(lenLimit(v.t), 1)} mm`, `Longueur maximale : ${nf(lenLimit(v.t), 1)} mm`) },
    ug: { f: [['F', ['Source size F', 'Taille de la source F'], 3, 'mm'], ['d', ['Object-to-film distance d', 'Distance objet-film d'], 25, 'mm'], ['D', ['Source-to-object distance D', 'Distance source-objet D'], 400, 'mm'], ['t', ['Thickness (IQI basis)', 'Épaisseur (base IQI)'], 25, 'mm']], run: (v) => { const u = v.F * v.d / v.D, lim = ugLimit(v.t), minD = v.F * v.d / lim; return L(`Ug = ${nf(u, 2)} mm · limit ${nf(lim, 2)} mm → ${u <= lim ? 'OK' : 'TOO HIGH'} · minimum D = ${nf(minD, 0)} mm`, `Ug = ${nf(u, 2)} mm · limite ${nf(lim, 2)} mm → ${u <= lim ? 'OK' : 'TROP ÉLEVÉ'} · D minimal = ${nf(minD, 0)} mm`); } },
    expo: { f: [['t1', ['Known good exposure', 'Pose correcte connue'], 4, 'min'], ['F1', ['at distance', 'à la distance'], 500, 'mm'], ['A1', ['with activity', 'avec l’activité'], 1500, 'GBq'], ['F2', ['New distance', 'Nouvelle distance'], 700, 'mm'], ['A2', ['New activity', 'Nouvelle activité'], 750, 'GBq']], run: (v) => { const t = v.t1 * Math.pow(v.F2 / v.F1, 2) * v.A1 / v.A2; return L(`New exposure = ${nf(v.t1, 1)} × (${v.F2} ÷ ${v.F1})² × (${v.A1} ÷ ${v.A2}) = ${nf(t, 1)} min — confirm on a test film`, `Nouvelle pose = ${nf(v.t1, 1)} × (${v.F2} ÷ ${v.F1})² × (${v.A1} ÷ ${v.A2}) = ${nf(t, 1)} min — à confirmer sur film d’essai`); } },
    shield: { f: [['r', ['Dose rate without shield', 'Débit de dose sans écran'], 800, 'µSv/h'], ['g', ['Wanted dose rate', 'Débit de dose voulu'], 25, 'µSv/h'], ['h', ['Half-value layer (lead)', 'Couche de demi-atténuation (plomb)'], 5, 'mm']], run: (v) => { const n = Math.max(0, Math.log2(v.r / v.g)); return L(`${nf(n, 1)} half-value layers → about ${nf(n * v.h, 1)} mm of lead (estimate; check with the survey meter)`, `${nf(n, 1)} couches de demi-atténuation → environ ${nf(n * v.h, 1)} mm de plomb (estimation ; à vérifier au radiamètre)`); } }
  };
  function toolHtml(k) {
    const c = TOOLS[k];
    return `<div class="cypc-tool" data-pc-tool="${k}"><b>🧮 ${L('Try it', 'Essayez')}</b> ${c.f.map(([n, l, d, u]) => `<label>${esc(T2(l))} <input data-pc-f="${n}" type="number" min="0" step="any" value="${d}"> ${esc(u)}</label>`).join(' ')} <span data-pc-out></span></div>`;
  }
  function refreshTool() {
    const box = ui.body.querySelector('[data-pc-tool]'); if (!box) return;
    const c = TOOLS[box.dataset.pcTool], v = {}; let ok = true;
    box.querySelectorAll('[data-pc-f]').forEach((i) => { v[i.dataset.pcF] = Number(i.value); if (!(Number(i.value) > 0)) ok = false; });
    box.querySelector('[data-pc-out]').textContent = ok ? c.run(v) : '—';
  }

  /* ---------- player ---------- */
  const css = `
.cypc-pick { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 10px; } .cypc-pick button { text-align: left; padding: 14px; display: grid; gap: 4px; border-radius: 12px; } .cypc-pick small { color: var(--muted); } .cypc-pick button.done { border-color: #42c991; } .cypc-card { display: grid; gap: 5px; grid-template-rows: 1fr auto; } .cypc-pick button.cypc-film, .cypc-bar button.cypc-film { background: linear-gradient(90deg, #2b7fd8, #7a4dff); border-color: transparent; color: #fff; font-weight: 700; text-align: center; padding: 8px 12px; }
.cypc-layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 14px; min-height: 100%; }
.cypc-side button { display: block; width: 100%; text-align: left; font-size: 12.5px; padding: 6px 8px; margin: 2px 0; border-color: transparent; background: transparent; } .cypc-side button.on { background: var(--accent); color: #fff; }
.cypc-slide { border: 1px solid var(--line); border-radius: 12px; padding: 16px 18px; background: linear-gradient(145deg, rgba(18,29,59,.95), rgba(13,20,47,.92)); animation: cypc-in .3s ease-out; } @keyframes cypc-in { from { opacity: 0; transform: translateX(14px); } to { opacity: 1; transform: none; } }
.cypc-slide h2 { margin: 0 0 10px; } .cypc-slide li { margin: 8px 0; line-height: 1.5; transition: opacity .3s, color .3s; color: #93a3cc; } .cypc-slide li.seen { color: #dce6ff; } .cypc-slide li.on { color: #fff; font-weight: 600; } .cypc-slide li.wait { opacity: .28; }
.cypc-table { width: 100%; border-collapse: collapse; margin: 12px 0 4px; font-size: 14px; } .cypc-table th { text-align: left; background: rgba(61,169,255,.16); padding: 7px 9px; } .cypc-table td { border-top: 1px solid var(--line); padding: 7px 9px; font-variant-numeric: tabular-nums; }
.cypc-src { font-size: 12px; color: var(--muted); margin: 4px 0 8px; } .cypc-st { display: inline-block; border-radius: 99px; padding: 1px 8px; font-weight: 700; font-size: 11px; margin-right: 6px; } .cypc-st.checked { background: rgba(28,106,78,.6); color: #7de2b5; } .cypc-st.verify { background: rgba(130,96,20,.6); color: #ffd27a; }
.cypc-tool { border: 1px dashed var(--blue); border-radius: 8px; padding: 8px 10px; margin: 8px 0; } .cypc-tool label { display: inline-block; margin: 3px 8px 3px 0; } .cypc-exam > div { border-top: 1px solid var(--line); padding: 8px 0; } .cypc-exam button.sel { border-color: var(--blue); background: rgba(61,169,255,.2); } .cypc-exam button { display: block; width: 100%; text-align: left; margin: 3px 0; } .cypc-exam .ok { border-color: #42c991; background: rgba(28,106,78,.45); } .cypc-exam .ko { border-color: #e66b78; background: rgba(130,47,61,.4); } .cypc-tool input { width: 80px; border: 1px solid var(--line); border-radius: 7px; background: var(--panel); color: var(--text); padding: 5px 7px; font: inherit; } .cypc-tool span { display: block; color: #7de2b5; font-weight: 700; margin-top: 4px; }
.cypc-q { border-top: 1px solid var(--line); margin-top: 10px; padding-top: 8px; } .cypc-q button { display: block; width: 100%; text-align: left; margin: 4px 0; } .cypc-q .ok { border-color: #42c991; background: rgba(28,106,78,.45); } .cypc-q .ko { border-color: #e66b78; background: rgba(130,47,61,.4); }
.cypc-bar { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; margin-top: 10px; } .cypc-bar .sp { flex: 1; } .cypc-prog { height: 5px; border-radius: 99px; background: rgba(255,255,255,.1); overflow: hidden; margin: 0 0 10px; } .cypc-prog i { display: block; height: 100%; background: linear-gradient(90deg, var(--blue), var(--violet)); transition: width .3s; }
@media (max-width: 760px) { .cypc-layout { grid-template-columns: minmax(0, 1fr); } .cypc-side { display: flex; overflow-x: auto; gap: 4px; } .cypc-side button { white-space: nowrap; width: auto; } .cypc-table { font-size: 12.5px; } }
@media (prefers-reduced-motion: reduce) { .cypc-slide { animation: none; } }
`;
  const KEY = 'cyclops-procourse-v1';
  const done = () => { try { return JSON.parse(localStorage.getItem(KEY) || '{}'); } catch { return {}; } };
  const mark = (m, i) => { const d = done(); d[m] = Math.max(d[m] || 0, i + 1); try { localStorage.setItem(KEY, JSON.stringify(d)); } catch { /* storage unavailable */ } };
  const st = { m: null, i: 0, b: 0, playing: false, voice: true, timer: 0, tok: 0 };
  let ui = null;
  const synth = () => (typeof speechSynthesis !== 'undefined' ? speechSynthesis : null);
  const stop = () => { st.tok++; clearTimeout(st.timer); const s = synth(); if (s) s.cancel(); };
  function open(course) {
    if (!window.CYLAB) return; stop(); st.playing = false;
    if (!document.getElementById('cypc-css')) { const s = document.createElement('style'); s.id = 'cypc-css'; s.textContent = css; document.head.appendChild(s); }
    ui = window.CYLAB.shell({ cls: 'cypc', title: '🎓 ' + L('Professional courses', 'Cours professionnels'), sub: L('Code requirements and acceptance criteria — working summaries, always check the edition in force', 'Exigences des codes et critères d’acceptation — résumés de travail, vérifiez toujours l’édition en vigueur') });
    ui.dlg.addEventListener('close', stop); ui.dlg.addEventListener('click', onClick); ui.dlg.addEventListener('input', onInput);
    if (COURSES[course]) start(course); else pick();
  }
  function pick() {
    stop(); st.m = null; const d = done();
    ui.body.innerHTML = `<p>${L('Narrated presentations for working inspectors. Each table shows its source and a badge:', 'Présentations commentées pour inspecteurs en activité. Chaque tableau indique sa source et un badge :')} <span class="cypc-st checked">${L('cross-checked', 'recoupé')}</span>${L('with public sources,', 'avec des sources publiques,')} <span class="cypc-st verify">${L('verify', 'à vérifier')}</span>${L('from training knowledge. None replaces the code text.', 'issu de connaissances de formation. Rien ne remplace le texte du code.')}</p>
<div class="cypc-pick">${ORDER.map((m) => { const c = COURSES[m], n = c.slides.length, s = Math.min(d[m] || 0, n); return `<div class="cypc-card"><button type="button" data-pc="${m}" class="${s >= n ? 'done' : ''}"><b>${c.icon} ${esc(T2(c.name))}</b><small>${esc(c.codes)}</small><small>${n} ${L('slides', 'diapositives')} · ${s}/${n} ${L('seen', 'vues')}</small></button>${window.CYFILM ? `<button type="button" class="cypc-film" data-pc-film-m="${m}">🎬 ${L('Watch the 3D video', 'Voir la vidéo 3D')}</button>` : ''}</div>`; }).join('')}</div>
<p class="cylab-note">${L('Training content, not a certification. The code edition in force, the contract, the approved procedure and the qualified inspector decide. National regulation can be stricter. Add your AQCS procedures and licensed codes to the documents folder so the AI assistant can cite them.', 'Contenu de formation, pas une certification. L’édition du code en vigueur, le contrat, la procédure approuvée et l’inspecteur qualifié décident. La réglementation nationale peut être plus stricte. Ajoutez vos procédures AQCS et codes sous licence dans le dossier documents pour que l’assistant IA puisse les citer.')}</p>`;
  }
  function start(m) { st.m = m; st.i = 0; st.playing = false; draw(); window.CY_LESSON = L('Professional course: ', 'Cours professionnel : ') + T2(COURSES[m].name); window.dispatchEvent(new CustomEvent('cy-learn', { detail: { id: 'pro:' + m } })); }
  function draw() {
    const c = COURSES[st.m], s = c.slides[st.i]; st.b = st.playing ? 0 : s.b.length; if (s.exam && !s.sel) prepExam(s);
    ui.body.innerHTML = `<div class="cypc-layout"><div class="cypc-side"><button type="button" data-pc-back="1">← ${L('All courses', 'Tous les cours')}</button>${c.slides.map((x, k) => `<button type="button" data-pc-i="${k}" class="${k === st.i ? 'on' : ''}">${k + 1}. ${esc(T2(x.t))}</button>`).join('')}</div>
<div><div class="cypc-prog"><i style="width:${(st.i + 1) / c.slides.length * 100}%"></i></div><div class="cypc-slide"><small style="color:var(--blue);font-weight:700">${c.icon} ${esc(T2(c.name))} · ${st.i + 1}/${c.slides.length}</small><h2>${esc(T2(s.t))}</h2>
<ul>${s.b.map((p, k) => `<li data-pc-b="${k}">${esc(T2(p))}</li>`).join('')}</ul>
${s.table ? `<table class="cypc-table"><tr>${s.table.head.map((h) => `<th>${esc(T2(h))}</th>`).join('')}</tr>${s.table.rows.map((r) => `<tr>${r.map((v) => `<td>${esc(T2(v))}</td>`).join('')}</tr>`).join('')}</table><p class="cypc-src"><span class="cypc-st ${s.table.st}">${s.table.st === 'checked' ? L('cross-checked', 'recoupé') : L('verify', 'à vérifier')}</span>${esc(s.table.src)} — ${L('working summary: check the edition in force.', 'résumé de travail : vérifiez l’édition en vigueur.')}</p>` : ''}
${s.tool ? toolHtml(s.tool) : ''}
${s.open ? `<p><button type="button" data-pc-open="1">🖥 ${esc(T2(s.open.label))}</button></p>` : ''}
${s.exam ? examHtml(s) : ''}
${s.q ? `<div class="cypc-q"><b>✅ ${esc(T2(s.q.q))}</b>${s.q.o.map((o, k) => [o, k]).sort(() => Math.random() - 0.5).map(([o, k]) => `<button type="button" data-pc-o="${k}">${esc(T2(o))}</button>`).join('')}<div data-pc-fb></div></div>` : ''}</div>
<div class="cypc-bar">${window.CYFILM ? `<button type="button" class="cypc-film" data-pc-film="1">🎬 ${L('3D video', 'Vidéo 3D')}</button>` : ''}<button type="button" data-pc-nav="-1">⏮</button><button type="button" data-pc-play="1">${st.playing ? '⏸' : '▶ ' + L('Present with voice', 'Présenter avec la voix')}</button><button type="button" data-pc-nav="1">⏭</button><button type="button" data-pc-voice="1">${st.voice ? '🔊' : '🔇'}</button><span class="sp"></span><button type="button" data-pc-ai="1">🤖 ${L('Ask the AI about this slide', 'Interroger l’IA sur cette diapositive')}</button></div></div></div>`;
    paint(); mark(st.m, st.i);
    refreshTool();
  }
  function examHtml(s) {
    const r = s.result;
    return `<div class="cypc-exam">${s.exam.map((q, i) => `<div data-pc-eq="${i}"><b>${i + 1}. ${esc(T2(q.q))}</b>${q.order.map((k) => `<button type="button" data-pc-x="${i}:${k}" class="${r ? (k === q.a ? 'ok' : k === s.sel[i] ? 'ko' : '') : (s.sel[i] === k ? 'sel' : '')}" ${r ? 'disabled' : ''}>${esc(T2(q.o[k]))}</button>`).join('')}${r ? `<small>💡 ${esc(T2(q.why))}</small>` : ''}</div>`).join('')}
${r ? `<p class="cysurf-score"><b>${r.score}/${s.exam.length} (${r.pct} %)</b> — ${r.pct >= 80 ? L('Passed the course exam. This is a training result, not a certification.', 'Examen du cours réussi. C’est un résultat de formation, pas une certification.') : L('Below 80 %: review the slides and your coach, then try again.', 'Sous 80 % : revoyez les diapositives et votre coach, puis recommencez.')}</p><button type="button" data-pc-retry="1">↻ ${L('New attempt', 'Nouvel essai')}</button>` : `<button type="button" class="cysurf-primary" data-pc-submit="1">✔ ${L('Finish the exam', 'Terminer l’examen')}</button>`}</div>`;
  }
  const prepExam = (s) => { s.sel = {}; s.result = null; s.exam.forEach((q) => { q.order = q.o.map((_, k) => k).sort(() => Math.random() - 0.5); }); };
  function paint() { ui.body.querySelectorAll('[data-pc-b]').forEach((li) => { const k = Number(li.dataset.pcB); li.className = st.playing ? (k < st.b ? 'seen' : k === st.b ? 'on' : 'wait') : 'seen'; }); }
  function say() {
    stop(); const c = COURSES[st.m], s = c.slides[st.i], my = st.tok; if (!st.playing) return;
    if (st.b >= s.b.length) { // slide finished: wait on a question, otherwise move on
      if ((s.q && !s.answered) || s.exam) return;
      if (st.i >= c.slides.length - 1) { st.playing = false; return draw(); }
      st.timer = setTimeout(() => { if (my === st.tok) { st.i++; st.b = 0; draw(); paint(); say(); } }, 900); return;
    }
    paint(); const text = T2(s.b[st.b]), S = synth(), next = () => { if (my === st.tok) { st.b++; say(); } };
    const v = S && st.voice && S.getVoices().filter((x) => x.lang && x.lang.toLowerCase().startsWith(L('en', 'fr')));
    if (v && v.length) { const u = new SpeechSynthesisUtterance(text); u.lang = L('en-US', 'fr-FR'); u.voice = v.find((x) => /natural|online|neural|google/i.test(x.name)) || v[0]; u.onend = next; u.onerror = next; S.speak(u); }
    else st.timer = setTimeout(next, Math.max(2500, text.split(/\s+/).length / 2.5 * 1000));
  }
  // the same slides, played as a narrated 3D film (cyclops-film.js)
  function film() {
    stop(); st.playing = false; const m = st.m; draw();
    window.CYFILM.play(m, st.i, { onSlide: (i) => mark(m, i), onClose: (i) => { if (st.m === m && ui && ui.dlg.open) { st.i = i; st.b = 0; draw(); } } });
  }
  function onClick(e) {
    const b = e.target.closest('button'); if (!b) return; const d = b.dataset;
    if (d.pcFilmM) { start(d.pcFilmM); return film(); }
    if (d.pcFilm) return film();
    if (d.pc) return start(d.pc);
    if (d.pcBack) return pick();
    if (d.pcOpen) { const o = COURSES[st.m].slides[st.i].open; stop(); ui.close(); if (o.twin && window.CYTWIN) window.CYTWIN.open(o.twin); else if (window.CYHOME) window.CYHOME.procedures(o.m, o.sel, o.mode); return; }
    if (d.pcX) { const [i, k] = d.pcX.split(':').map(Number), s = COURSES[st.m].slides[st.i]; if (s.result) return; s.sel[i] = k; b.parentElement.querySelectorAll('[data-pc-x]').forEach((x) => x.classList.toggle('sel', x === b)); return; }
    if (d.pcSubmit) {
      const s = COURSES[st.m].slides[st.i], miss = s.exam.findIndex((_, i) => s.sel[i] == null);
      if (miss >= 0) { ui.body.querySelector('[data-pc-eq="' + miss + '"]').scrollIntoView({ block: 'center' }); return; }
      let n = 0; s.exam.forEach((q, i) => { const ok = s.sel[i] === q.a; if (ok) n++; window.dispatchEvent(new CustomEvent('cy-answer', { detail: { src: 'pro-exam', area: st.m, skill: 'codes', ok, q: q.q, given: q.o[s.sel[i]], right: q.o[q.a], why: q.why } })); });
      s.result = { score: n, pct: Math.round(n / s.exam.length * 100) };
      window.dispatchEvent(new CustomEvent('cy-learn', { detail: { id: 'pro-exam:' + st.m, score: s.result.pct } }));
      draw(); return;
    }
    if (d.pcRetry) { prepExam(COURSES[st.m].slides[st.i]); draw(); return; }
    if (d.pcI != null) { st.i = Number(d.pcI); st.b = 0; draw(); if (st.playing) say(); return; }
    if (d.pcNav) { const n = COURSES[st.m].slides.length; st.i = Math.max(0, Math.min(n - 1, st.i + Number(d.pcNav))); st.b = 0; draw(); if (st.playing) say(); return; }
    if (d.pcPlay) { st.playing = !st.playing; const i = st.i; if (st.playing) { st.b = 0; COURSES[st.m].slides[i].answered = false; } else stop(); draw(); if (st.playing) { paint(); say(); } return; }
    if (d.pcVoice) { st.voice = !st.voice; b.textContent = st.voice ? '🔊' : '🔇'; if (st.playing) say(); return; }
    if (d.pcAi) { const s = COURSES[st.m].slides[st.i]; ui.close(); if (window.CY3 && window.CY3.send) { window.CY3.open(); window.CY3.send(L('Explain this topic for a working inspector, with an example, and say what to verify in the code: ', 'Explique ce sujet pour un inspecteur en activité, avec un exemple, et dis ce qu’il faut vérifier dans le code : ') + T2(COURSES[st.m].name) + ' — ' + T2(s.t)); } return; }
    if (d.pcO != null && b.closest('.cypc-q')) {
      const s = COURSES[st.m].slides[st.i], q = s.q, box = b.closest('.cypc-q'); if (box.dataset.done) return; box.dataset.done = '1'; const ok = Number(d.pcO) === q.a;
      box.querySelectorAll('button').forEach((x) => { if (Number(x.dataset.pcO) === q.a) x.classList.add('ok'); else if (x === b) x.classList.add('ko'); });
      box.querySelector('[data-pc-fb]').innerHTML = `<div class="cyac-fb" style="padding:6px 10px;border-left:3px solid var(--blue);margin-top:6px">${ok ? '✅' : '❌'} ${esc(T2(q.why))}</div>`;
      window.dispatchEvent(new CustomEvent('cy-answer', { detail: { src: 'pro-course', area: st.m, skill: 'codes', ok, q: q.q, given: q.o[Number(d.pcO)], right: q.o[q.a], why: q.why } }));
      s.answered = true; if (st.playing) { const my = st.tok; st.timer = setTimeout(() => { if (my === st.tok) say(); }, 2500); }
    }
  }
  function onInput(e) { if (e.target.dataset && e.target.dataset.pcF) refreshTool(); }
  window.CYPRO = { open, COURSES, TB, TOOLS };
  if (window.CYLAB) window.CYLAB.register({ icon: '🎓', available: () => true, open: () => open(), title: () => L('Professional courses', 'Cours professionnels'), desc: () => L('Narrated courses with code requirements and acceptance criteria: UT, RT, MT, PT, VT, APVG, APL, APE.', 'Cours commentés avec exigences des codes et critères d’acceptation : UT, RT, MT, PT, VT, APVG, APL, APE.') });
}());
